-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0037', 'Stellenbosch', '{}'::text[], 'ZA', -33.990, 18.841, 16,
   'Mountain slopes and valleys with deep, well drained soils from granite, shale and sandstone. Known for blended reds and Cabernet Sauvignon, while Syrah and Chenin Blanc also do well.',
   null, null, null, null, 'Production area (district) defined under the name Stellenbosch (Board Notice 37 of 2004). SAWIS lists it in the Coastal Region.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0038', 'Franschhoek', '{"Franschhoek Valley","Franschhoek Vallei"}'::text[], 'ZA', -33.896, 19.107, 7,
   'A valley southeast of Paarl, enclosed by mountains on three sides. The grape most tied to it is Semillon, some from very old vines, and Chardonnay is another strength.',
   null, null, null, null, 'Defined as a district under the name "Franschhoek/Franschhoek Valley" (Board Notice 64 of 2010); SAWIS (Feb 2026) also gives the Afrikaans form Franschhoek Vallei.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0039', 'Paarl', '{}'::text[], 'ZA', -33.733, 18.974, 18,
   'Lies north of Stellenbosch and is the warmer of the two, with a hot growing season. Cabernet Sauvignon, Shiraz, Chenin Blanc and Chardonnay all do well here.',
   null, null, null, null, 'Production area (district) Paarl, Coastal Region (SAWIS production areas list, Feb 2026). Defining notice not located.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0040', 'Swartland', '{}'::text[], 'ZA', -33.035, 18.596, 57,
   'A large, warm and dry district north of Cape Town, with many old bush vines farmed without irrigation. Syrah and Cinsault stand out among the reds, with Chenin Blanc for whites.',
   null, null, null, null, 'Production area (district) Swartland, Coastal Region (SAWIS production areas list, Feb 2026). Defining notice not located.',
   'https://www.winespectator.com/articles/abcs-of-south-africa-42847', 'published'),
  ('wr_0041', 'Constantia', '{}'::text[], 'ZA', -34.041, 18.411, 5,
   'Cool, ocean influenced slopes of the Table Mountain range above False Bay, on mainly granite soils. Whites lead, above all Sauvignon Blanc, and the valley is home to the historic sweet wine Vin de Constance.',
   null, null, null, null, 'A ward (production area) named Constantia (Board Notice 179 of 2010), listed by SAWIS under the Cape Town district, Coastal Region.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0042', 'Elgin', '{}'::text[], 'ZA', -34.206, 19.076, 12,
   'A high, cool district between about 250 and 500 m in the Hottentots Holland mountains, once mainly apple country. Sauvignon Blanc is the most planted grape, then Chardonnay and Pinot Noir, with some Syrah.',
   null, null, null, null, 'Production area (district) Elgin, Cape South Coast region (Board Notice 189 of 2011; SAWIS Feb 2026). It has no wards.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0043', 'Walker Bay', '{}'::text[], 'ZA', -34.380, 19.191, 17,
   'A cool coastal district around Hermanus, cooled by winds off the cold ocean, on largely shale soils. Chardonnay and Pinot Noir from the Hemel-en-Aarde valleys lead.',
   null, null, null, null, 'Production area (district) Walker Bay, Cape South Coast region (Board Notice 59 of 2004; SAWIS Feb 2026). Hemel-en-Aarde is not itself a production area: the three Hemel-en-Aarde names are separate wards.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0044', 'Barossa Valley', '{}'::text[], 'AU', -34.535, 138.936, 14,
   'A warm valley with a Mediterranean climate of cool, wet winters and warm, dry summers, on soils from clay loam to sand. It is known for full bodied, ripe Shiraz, some from very old vines.',
   5, null, null, null, 'A wine labelled with Barossa Valley as its only GI must contain at least 85% wine from grapes grown in the Barossa Valley GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/south-australia/barossa-valley-wine-region', 'published'),
  ('wr_0045', 'McLaren Vale', '{}'::text[], 'AU', -35.202, 138.562, 12,
   'A warm Mediterranean region on the coast south of Adelaide, cooled by sea breezes and set on very varied soils. Its Shiraz is rich and medium to full bodied, often with chocolate notes, and old vine Grenache grows on sand.',
   4, null, null, null, 'A wine labelled with McLaren Vale as its only GI must contain at least 85% wine from grapes grown in the McLaren Vale GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/south-australia/mclaren-vale-wine-region', 'published'),
  ('wr_0046', 'Clare Valley', '{}'::text[], 'AU', -33.909, 138.651, 15,
   'A valley in the northern Mount Lofty Ranges where warm days give way to cold nights and afternoon breezes, on varied soils that include slate. It is best known for dry, lime scented Riesling, alongside Shiraz and Cabernet Sauvignon.',
   null, null, null, 'Dry Riesling with shellfish, seafood and Asian dishes.', 'A wine labelled with Clare Valley as its only GI must contain at least 85% wine from grapes grown in the Clare Valley GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/south-australia/clare-valley-wine-region', 'published'),
  ('wr_0047', 'Coonawarra', '{}'::text[], 'AU', -37.266, 140.883, 11,
   'A cool region with a maritime influence in the south east of South Australia, known for a narrow strip of red terra rossa soil over limestone. Its Cabernet Sauvignon shows blackcurrant and plum fruit, and the best wines age well.',
   null, null, null, null, 'A wine labelled with Coonawarra as its only GI must contain at least 85% wine from grapes grown in the Coonawarra GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/discover-australian-wine/south-australia-wines/coonawarra', 'published'),
  ('wr_0048', 'Adelaide Hills', '{}'::text[], 'AU', -35.023, 138.803, 22,
   'A cool, elevated region in the Mount Lofty Ranges east of Adelaide, mostly on loamy sands and loams over clay. Grapes keep good natural acidity, giving fresh Sauvignon Blanc, Chardonnay, Pinot Noir and sparkling wine.',
   null, null, null, null, 'A wine labelled with Adelaide Hills as its only GI must contain at least 85% wine from grapes grown in the Adelaide Hills GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/south-australia/adelaide-hills-wine-region', 'published'),
  ('wr_0049', 'Hunter', '{"Hunter Valley"}'::text[], 'AU', -32.377, 150.944, 80,
   'A warm, humid region where cloud cover and sea breezes temper the heat. Its Semillon, grown on sandy alluvial flats, is picked early, low in alcohol and unoaked, and can age for decades; its Shiraz is medium bodied.',
   3, null, null, 'Young Semillon with seafood such as prawns, crab and white fish.', 'A wine labelled with Hunter as its only GI must contain at least 85% wine from grapes grown in the Hunter GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/discover-australian-wine/new-south-wales-wines/hunter-valley', 'published'),
  ('wr_0050', 'Yarra Valley', '{}'::text[], 'AU', -37.724, 145.630, 32,
   'A cool region east of Melbourne, with grey brown sandy loam on the northern side of the valley and red volcanic soil on the southern side. Pinot Noir and Chardonnay lead, and the Pinot Noir is light to medium bodied.',
   2, null, null, null, 'A wine labelled with Yarra Valley as its only GI must contain at least 85% wine from grapes grown in the Yarra Valley GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/en-AU/our-places/victoria/yarra-valley-wine-region', 'published'),
  ('wr_0051', 'Margaret River', '{}'::text[], 'AU', -33.940, 115.144, 26,
   'A Mediterranean region with a strong maritime influence in the far south west of Western Australia, on gravelly, iron rich soils. Cabernet Sauvignon is its flagship red, alongside Chardonnay and crisp Semillon and Sauvignon Blanc blends.',
   3, null, null, null, 'A wine labelled with Margaret River as its only GI must contain at least 85% wine from grapes grown in the Margaret River GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/discover-australian-wine/western-australia-wines/margaret-river', 'published'),
  ('wr_0052', 'Tasmania', '{}'::text[], 'AU', -42.111, 146.672, 149,
   'The coolest and most southerly of Australia''s wine regions, an island state with very varied soils. It is known for Pinot Noir, Chardonnay with high natural acidity, and traditional method sparkling wine made mainly from those two grapes.',
   2, null, null, null, 'A wine labelled with Tasmania as its only GI must contain at least 85% wine from grapes grown in the Tasmania GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/market-insights/regions-and-varieties/tasmania-wines/tasmania', 'published'),
  ('wr_0053', 'Marlborough', '{}'::text[], 'NZ', -41.664, 173.608, 66,
   'New Zealand''s largest wine region, with a sunny, dry maritime climate and soils from old river deposits to clay. Sauvignon Blanc is pungent and aromatic, with tropical fruit and green herbs; Pinot Noir does best on heavier soils.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/marlborough/', 'published'),
  ('wr_0054', 'Hawke''s Bay', '{"Hawkes Bay"}'::text[], 'NZ', -39.495, 176.543, 68,
   'On the North Island''s east coast, with a temperate, maritime climate and free-draining alluvial plains and gravels, the Gimblett Gravels the best known. Its strengths are Chardonnay, Bordeaux-style red blends and aromatic, elegant Syrah.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/hawkesbay/', 'published'),
  ('wr_0055', 'Central Otago', '{}'::text[], 'NZ', -44.892, 169.087, 79,
   'Inland in the far south of the South Island, with a dry climate of hot summer days and cold nights, and stony, free-draining soils. Pinot Noir fills about four fifths of the vineyards and gives intense wines with lush fruit.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/centralotago/', 'published'),
  ('wr_0056', 'North Canterbury', '{}'::text[], 'NZ', -42.998, 172.188, 78,
   'Spread north and south of Christchurch, on river gravels and limestone clays, with the Waipara Valley warmer than the rest. It is known for Riesling and for Pinot Noir from its clay and limestone soils.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/northcanterbury/', 'published'),
  ('wr_0057', 'Gisborne', '{}'::text[], 'NZ', -38.259, 177.906, 52,
   'One of New Zealand''s sunniest and warmest wine regions, with soils that change from one subregion to the next. It is best known for Chardonnay with rich, generous fruit, grown alongside Sauvignon Blanc and Pinot Gris.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/gisborne/', 'published'),
  ('wr_0058', 'Wairarapa', '{}'::text[], 'NZ', -41.150, 175.616, 44,
   'Close to Wellington, with a cool, sunny climate, wide swings between day and night and free-draining river terraces. Pinot Noir and Sauvignon Blanc lead, and Martinborough made its name with Pinot Noir.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/wairarapa/', 'published'),
  ('wr_0059', 'Nelson', '{}'::text[], 'NZ', -41.406, 172.910, 57,
   'A sheltered region with high sunshine and a moderating coastal climate. Sauvignon Blanc leads; the stony Waimea Plains and the clay soils of the Moutere Hills, which give richer, more textured wines, are its two main areas.',
   null, null, null, null, 'A wine may carry a New Zealand GI only if at least 85% of it comes from grapes harvested in that GI and any remainder from grapes harvested in New Zealand (Geographical Indications (Wine and Spirits) Registration Act 2006, sections 21 to 26).',
   'https://www.nzwine.com/en/regions/nelson/', 'published'),
  ('wr_0060', 'Hrvatska Istra', '{"Istria","Croatian Istria","Istra"}'::text[], 'HR', 45.120, 13.909, 30,
   'Istria is led by Malvazija Istarska, a floral, gently spicy white made fresh and young or richer and oak aged. Teran, the native red, is deep coloured with high acidity and firm tannins.',
   4, 4, 4, null, 'The grape name Teran may be used only on Hrvatska Istra wines, in the same field of view as the region name and in smaller letters.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/40080', 'published'),
  ('wr_0061', 'Srednja i Južna Dalmacija', '{"Central and Southern Dalmatia","Central and South Dalmatia"}'::text[], 'HR', 43.154, 16.731, 35,
   'Coastal slopes and islands from Trogir to Konavle. Plavac Mali, the main grape, gives full, high alcohol reds with soft acidity, prized from steep sites such as Dingač. Pošip is the leading white.',
   4, 2, 4, null, 'Labels may carry Kvalitetno vino KZP or Vrhunsko vino KZP. Arhivsko vino means at least five years in the cellar, three of them in bottle.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/36383', 'published'),
  ('wr_0062', 'Slavonija', '{"Slavonia"}'::text[], 'HR', 45.515, 17.614, 50,
   'Inland eastern Croatia with a continental climate, built on Graševina. Riesling, Chardonnay and Pinot Gris follow, Frankovka leads the reds, and late harvest and ice wines are also made.',
   null, null, null, 'Fresh Graševina suits shellfish and other seafood.', 'Sweet wines use the terms Kasna berba, Izborna berba, Izborna berba bobica, Izborna berba prosušenih bobica and Ledeno vino, each with a minimum must weight.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/36373', 'published'),
  ('wr_0063', 'Hrvatsko Podunavlje', '{"Croatian Danube","Podunavlje"}'::text[], 'HR', 45.384, 18.740, 41,
   'The Danube side of eastern Croatia, around Ilok, Erdut and Baranja. Graševina leads, followed by Riesling, Chardonnay and Traminac, and late harvest and botrytis sweet wines are made near the river.',
   null, null, null, 'Fresh Graševina suits shellfish and other seafood.', 'Sweet wines use the terms Kasna berba, Izborna berba, Izborna berba bobica, Izborna berba prosušenih bobica and Ledeno vino, each with a minimum must weight.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/36303', 'published'),
  ('wr_0064', 'Plešivica', '{"Plesivica"}'::text[], 'HR', 45.686, 15.573, 19,
   'Hillside vineyards west of Zagreb, on the slopes of Plešivica and Žumberak, with a cool continental climate. The wines are mostly fresh whites with lively acidity, led by Graševina, Riesling and Chardonnay.',
   null, null, null, null, 'Sparkling wines may be labelled Vrhunsko pjenušavo vino; sweet wines use the terms Kasna berba, Izborna berba and Ledeno vino, among others.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/36343', 'published'),
  ('wr_0065', 'Valais', '{"Wallis","AOC Valais"}'::text[], 'CH', 46.243, 7.635, 41,
   'Switzerland''s largest wine region, on steep and sunny slopes. Pinot Noir and Chasselas, sold as Fendant, lead the plantings, beside local grapes such as Petite Arvine and Cornalin.',
   null, null, null, 'Game with Humagne Rouge.', '"AOC Valais" must appear in full on the main label. Grand Cru may only be used with the name of its commune or region; "Grand Cru Valais" is not allowed.',
   'https://www.newsd.admin.ch/newsd/message/attachments/91825.pdf', 'published'),
  ('wr_0066', 'Vaud', '{"Waadt","AOC Vaud"}'::text[], 'CH', 46.583, 6.474, 31,
   'Switzerland''s second largest wine canton and the only one where white grapes lead. Chasselas covers more than half the vineyard, across regions such as Chablais, Lavaux and La Côte.',
   null, null, null, 'Cheese fondue with Chasselas.', 'A Vaud AOC white with no grape named must be at least 90% Chasselas; a single named grape must make up at least 85% of the wine.',
   'https://www.newsd.admin.ch/newsd/message/attachments/91825.pdf', 'published'),
  ('wr_0067', 'Lavaux', '{"AOC Lavaux"}'::text[], 'CH', 46.504, 6.749, 8,
   'A regional appellation within Vaud covering the terraced vineyards east of Lausanne, listed by UNESCO in 2007. It contains the Dézaley and Calamin Grand Cru appellations.',
   null, null, null, null, 'Wines from Dézaley or Calamin may also use the Lavaux appellation. Blending with other wines (coupage) is not allowed for AOC Lavaux.',
   'https://www.lexfind.ch/tolv/261089/fr', 'published'),
  ('wr_0068', 'Genève', '{"Geneva","Genf","AOC Genève"}'::text[], 'CH', 46.212, 6.066, 10,
   'Vineyards around the city that continue over the border into France. Gamay is the most planted grape, just ahead of Chasselas, with Pinot Noir, Gamaret and Chardonnay next.',
   null, null, null, null, 'A commune or hamlet name may name an AOC Premier Cru only with an added term such as "Côte de" or "Coteau de". "Perlan" may appear on a still Chasselas.',
   'https://silgeneve.ch/legis/data/rsg_m2_50p05.htm', 'published'),
  ('wr_0069', 'Ticino', '{"Tessin","Ticino DOC"}'::text[], 'CH', 46.233, 8.861, 31,
   'Switzerland''s wine region south of the Alps. Merlot covers about three quarters of the vineyard, and reds dominate; Merlot is also made as a white, known as Merlot bianco.',
   null, null, 2, 'Red meat and mature cheeses.', 'A grape named on a DOC Ticino label must make up at least 90% of the wine; blends are sold as Rosso, Bianco or Rosato del Ticino.',
   'https://www.swisswine.com/en/swiss-wine-regions/ticino-wine-region', 'published'),
  ('wr_0070', 'Neuchâtel', '{"Neuenburg","AOC Neuchâtel"}'::text[], 'CH', 47.006, 6.809, 15,
   'A single cantonal AOC around Lake Neuchâtel. Pinot Noir and Chasselas are the main grapes, and the Non filtré, an unfiltered young Chasselas, is a local speciality.',
   null, null, null, null, 'Pinot Noir must contain at least 95% Pinot Noir. Non filtré is an unfiltered Chasselas released no earlier than the third Wednesday of January after harvest.',
   'https://web.archive.org/web/2020/https://www.ne.ch/legislation-jurisprudence/pubfo/ArrRegCE/Documents/2016/FO25_04_ACE_DDTE_A_Vins_NE_AOC.pdf', 'published'),
  ('wr_0071', 'Graubünden', '{"Grisons","Grigioni","AOC Graubünden"}'::text[], 'CH', 46.924, 9.592, 9,
   'Vineyards along the Rhine from Bonaduz to Fläsch, including the Bündner Herrschaft villages. Pinot Noir, called Blauburgunder here, covers about two thirds of the area, in a mild climate shaped by the foehn.',
   null, null, null, null, 'A commune name may be added when at least 60% of the wine comes from that commune; a vineyard site name requires 100%.',
   'https://www.swisswine.com/en/swiss-wine-regions/german-speaking-switzerland-wine-region/graubuenden-en', 'published'),
  ('wr_0072', 'Wachau', '{}'::text[], 'AT', 48.358, 15.424, 8,
   'A narrow stretch of the Danube valley with hot, dry summers and cold winters. Dry stone terraces on weathered gneiss, with loess in places, carry mostly Grüner Veltliner and Riesling, made as dry whites.',
   null, null, null, null, 'Wachau DAC has three origin levels: Gebietswein (regional, 17 permitted varieties), Ortswein (a named village or the Großlage Spitzer Graben, nine white varieties) and Riedenwein (a single vineyard, Grüner Veltliner or Riesling only, no chaptalisation). Grapes must be hand picked and the vintage is mandatory.',
   'https://www.bmluk.gv.at/dam/jcr:e3bf80c9-6295-4e83-b7c1-ab830c69f76a/Wachau%20Produktspezifikation.pdf', 'published'),
  ('wr_0073', 'Kremstal', '{}'::text[], 'AT', 48.406, 15.639, 7,
   'Vineyards around the town of Krems on the Danube. Weathered primary rock in the north suits Riesling, while the loess terraces east of the town give a rounder Grüner Veltliner. Both are the grapes of Kremstal DAC.',
   null, null, null, null, 'Kremstal DAC is Grüner Veltliner or Riesling, dry, with the vintage on the label. It may name a village from the annex (Ortsangabe) or a Ried, and Kremstal DAC Reserve (at least 13.0% vol) is a fuller style in which slight botrytis and oak are allowed.',
   'https://www.bmluk.gv.at/dam/jcr:1862785e-6b29-4856-8e65-55955bd4c9c4/Kremstal%20Produktspezifikation.pdf', 'published'),
  ('wr_0074', 'Kamptal', '{}'::text[], 'AT', 48.495, 15.672, 8,
   'The valley of the river Kamp around Langenlois, north of the Danube. Loess, gravel and very old primary rock soils, as on the Heiligenstein hill, carry the two main grapes, Grüner Veltliner and Riesling.',
   null, null, null, null, 'Kamptal DAC has three levels: Gebietswein, Ortswein (one of 12 cross-village wine communes listed in the annex) and Riedenwein. Permitted grapes are Grüner Veltliner, Riesling, Chardonnay, Weißburgunder and Grauburgunder. From the 2025 harvest the grapes must be certified organic or Nachhaltig Austria, with small-producer exceptions.',
   'https://www.bmluk.gv.at/dam/jcr:9034ac7d-a3bf-4c58-9d3a-24acc5f18df9/Produktspezifikation_Kamptal.pdf', 'published'),
  ('wr_0075', 'Wagram', '{}'::text[], 'AT', 48.352, 15.950, 15,
   'A long terrace of deep loess above the north bank of the Danube, plus the vineyards around Klosterneuburg south of the river. The loess gives full, flavoursome whites led by Grüner Veltliner; Zweigelt is the main red.',
   null, null, null, null, 'Wagram DAC is dry and carries the vintage. Gebietswein may use 13 varieties; Ortswein (named Katastralgemeinden only) seven single varieties; Riedenwein only Grüner Veltliner, Roter Veltliner or Riesling.',
   'https://www.bmluk.gv.at/dam/jcr:24c80f20-c06d-4159-b5bc-04feaeeadcad/Produktspezifikation_Wagram.pdf', 'published'),
  ('wr_0076', 'Weinviertel', '{}'::text[], 'AT', 48.510, 16.337, 40,
   'Austria''s largest wine region, covering the north east of Lower Austria. Its flagship is Grüner Veltliner: Weinviertel DAC is dry, fruity and spicy with a peppery note, without oak or botrytis.',
   null, null, null, 'Wiener Schnitzel and spicy Asian or vegetarian dishes.', 'Weinviertel DAC is Grüner Veltliner only, with at most 6 g/l residual sugar, no oak and no botrytis, and the vintage on the label. Weinviertel DAC Reserve (at least 13.0% vol) and Große Reserve are fuller styles; a village, Großlage or Ried may be named.',
   'https://www.weinvierteldac.at/en/?p=2665', 'published'),
  ('wr_0077', 'Leithaberg', '{"Neusiedlersee-Hügelland"}'::text[], 'AT', 47.857, 16.560, 14,
   'Between the Leitha hills and Lake Neusiedl, which tempers the climate. Leitha limestone and mica schist give tight, mineral wines: red Blaufränkisch, and whites from Pinot Blanc, Chardonnay and Grüner Veltliner.',
   null, null, null, null, 'Leithaberg DAC red must be Blaufränkisch; white must be Weißer Burgunder, Chardonnay, Neuburger, Grüner Veltliner or a blend of them. Both must be dry (reds below 2.5 g/l sugar) and may be Gebietswein or, with a narrower origin, Ortswein or Riedenwein.',
   'https://www.bmluk.gv.at/dam/jcr:a0809121-2a1f-4cf7-8034-f65a5515da94/Leithaberg%20Produktspezifikation.pdf', 'published'),
  ('wr_0078', 'Neusiedlersee', '{}'::text[], 'AT', 47.900, 16.947, 18,
   'East of Lake Neusiedl, with hot, dry summers and little rain. The lake moderates temperatures and its autumn mists bring noble rot. Fruity Zweigelt leads the reds, alongside sweet wines from white grapes.',
   null, null, null, null, 'Neusiedlersee DAC has four categories: Zweigelt (fruity, spicy, at most 4 g/l sugar, no Ried name), Zweigelt Reserve (aged in large casks or barrique, at least 13.0% vol), fruity sweet Spätlese or Auslese from white grapes, and nobly sweet Beerenauslese or Trockenbeerenauslese as Reserve. Sweet wines from Apetlon, Illmitz or Podersdorf may add „Seewinkel“.',
   'https://www.bmluk.gv.at/dam/jcr:4f785904-f6b1-4562-a83f-b3bf82e7ae33/Neusiedlersee%20Produktspezifikation.pdf', 'published'),
  ('wr_0079', 'Südsteiermark', '{"South Styria","Southern Styria"}'::text[], 'AT', 46.773, 15.464, 13,
   'Steep hills on the southern edge of the Graz basin, on sand, slate, marl and limestone. Warm days and cool nights give a long season and crisp, aromatic whites, led by Sauvignon Blanc.',
   null, null, null, null, 'Südsteiermark DAC is white only, from hand-picked grapes of eight varieties, at most 4 g/l sugar, with the vintage on the label. It has three levels: Gebietswein, Ortswein (Kitzeck-Sausal, Eichberg, Leutschach, Gamlitz or Ehrenhausen, each with set lead varieties) and Riedenwein.',
   'https://info.bml.gv.at/dam/jcr:fd136104-9145-4cfa-9d5a-4d4d76413f8a/S%C3%BCdsteiermark%20Produktspezifikation.pdf', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0032', 'Semillon', '{"Sémillon"}'::text[], 'white',
   'A white grape that once covered most of the Cape''s vineyards. It gives fuller bodied wines, and in South Africa it is closely tied to Franschhoek.',
   '{"Beeswax","Lemon","Peach"}'::text[], null, 4, null, null, 'published'),
  ('gr_0033', 'Cinsault', '{"Cinsaut","Hermitage"}'::text[], 'red',
   'A red grape making light, soft wines with bright red berry fruit. In South Africa it was long called Hermitage, and it is a parent of Pinotage.',
   '{"Red berries","Raspberry","Cherry"}'::text[], null, 2, null, 2, 'published'),
  ('gr_0034', 'Pinotage', '{}'::text[], 'red',
   'South Africa''s own red grape, a cross of Pinot Noir and Cinsault first made in 1925 by Abraham Perold. Ripe red and black fruit, often with a smoky edge.',
   '{"Red fruit","Blackberry","Smoke"}'::text[], 'Gains complexity with age.', null, null, null, 'published'),
  ('gr_0035', 'Malvazija Istarska', '{"Malvazija","Vrbić","Očenaš"}'::text[], 'white',
   'Istria''s leading white grape. Floral and gently spicy, it is made in many styles, from fresh and young to oak aged, skin contact, sparkling and sweet.',
   '{"Floral","Honey","Spice"}'::text[], 'Also made in oak, often acacia, which gives a richer, fuller style.', null, null, null, 'published'),
  ('gr_0036', 'Teran', '{"Istrijanac"}'::text[], 'red',
   'Istria''s native red. Deep ruby with violet tones, it has high acidity and firm tannins, with forest berry and raspberry fruit.',
   '{"Raspberry","Forest berries","Violet"}'::text[], 'With age it gains vanilla, jam and spice notes, and it responds well to barrel ageing.', 4, 4, 4, 'published'),
  ('gr_0037', 'Plavac Mali', '{"Plavac mali crni","Plavac veliki","Crljenak mali"}'::text[], 'red',
   'Dalmatia''s main red grape, a cross of Tribidrag (Zinfandel) and Dobričić. It gives full, high alcohol reds with plenty of tannin and soft acidity.',
   '{"Dark cherry","Plum","Dried fig"}'::text[], 'Tannins soften with age, and the best wines become fuller, rounder and softer.', 4, 2, 4, 'published'),
  ('gr_0038', 'Pošip', '{"Pošip bijeli","Pošipak","Pošipica"}'::text[], 'white',
   'A native Dalmatian white grape, the most planted white in central and southern Dalmatia. Its wines are full bodied, with stone fruit and citrus notes.',
   '{"Peach","Citrus"}'::text[], null, 4, null, null, 'published'),
  ('gr_0039', 'Graševina', '{"Welschriesling","Laški rizling","Riesling Italico","Olasz Rizling"}'::text[], 'white',
   'Croatia''s most planted white, known elsewhere as Welschriesling. Usually dry and fresh with apple and citrus notes; late harvest and other sweet styles are also made.',
   '{"Apple","Citrus"}'::text[], null, null, 4, null, 'published'),
  ('gr_0040', 'Blaufränkisch', '{"Frankovka","Kékfrankos","Lemberger","Frankinja"}'::text[], 'red',
   'A red grape known as Kékfrankos in Hungary, Lemberger in Germany and Frankovka in Croatia. It gives dark fruited, spicy wines with fresh acidity and firm tannins.',
   '{"Black cherry","Blackberry","Spice"}'::text[], 'Tannins soften after a few years in bottle; good examples keep for up to about ten years.', 3, 4, 4, 'published'),
  ('gr_0041', 'Gewürztraminer', '{"Traminac","Traminac crveni","Traminac mirisavi","Roter Traminer"}'::text[], 'white',
   'A highly aromatic white grape, called Traminac in Croatia. Known for lychee and rose, it makes rich, round wines with soft acidity, from dry to sweet.',
   '{"Lychee","Rose","Ginger","Grapefruit"}'::text[], null, 4, 2, null, 'published'),
  ('gr_0042', 'Chasselas', '{"Fendant","Gutedel"}'::text[], 'white',
   'Switzerland''s main white grape, sold as Fendant in Valais. It gives light, dry wines with floral, apple and citrus notes.',
   '{"Lime blossom","Apple","Citrus","Mineral"}'::text[], null, 2, null, null, 'published'),
  ('gr_0043', 'Petite Arvine', '{"Arvine"}'::text[], 'white',
   'A white grape grown almost only in Valais. Its wines pair grapefruit and rhubarb with lively acidity and a salty finish.',
   '{"Grapefruit","Rhubarb","Wisteria","Salty finish"}'::text[], null, null, 4, null, 'published'),
  ('gr_0044', 'Cornalin', '{"Rouge du Pays","Cornalin du Valais","Landroter"}'::text[], 'red',
   'A red grape from the Aosta Valley, now grown almost only in Valais, where it is also called Rouge du Pays. It gives black cherry fruit and firm tannins.',
   '{"Black cherry","Clove"}'::text[], null, null, null, 4, 'published'),
  ('gr_0045', 'Humagne Rouge', '{}'::text[], 'red',
   'A red grape from the Aosta Valley, now grown almost only in Valais. Its violet scented wines are often matched with game.',
   '{"Violet"}'::text[], null, null, null, null, 'published'),
  ('gr_0046', 'Gamaret', '{}'::text[], 'red',
   'A Swiss red cross of Gamay and Reichensteiner, grown mostly in Vaud, Geneva and Valais, where it gives spicy, tannic red wines.',
   '{"Spice"}'::text[], null, null, null, null, 'published'),
  ('gr_0047', 'Grüner Veltliner', '{"Veltlínské zelené"}'::text[], 'white',
   'A white grape native to Austria, a natural crossing of Traminer and St. Georgener-Rebe. It gives dry wines with high acidity, citrus fruit and a white pepper note.',
   '{"Lemon and lime","White pepper","Green herbs"}'::text[], 'Top wines can age for ten years or more.', 2, 4, null, 'published'),
  ('gr_0048', 'Zweigelt', '{"Blauer Zweigelt","Rotburger"}'::text[], 'red',
   'Austria''s most planted red grape, a 1922 crossing of Blaufränkisch and St. Laurent. It makes soft, approachable reds with red fruit and spice.',
   '{"Red cherry","Raspberry","Pepper"}'::text[], null, 2, null, 2, 'published'),
  ('gr_0049', 'Pinot Blanc', '{"Weissburgunder","Weißburgunder","Klevner"}'::text[], 'white',
   'A white grape called Weissburgunder in Austria. It gives dry wines with citrus and stone fruit notes and a mineral edge, usually made to drink young.',
   '{"Lemon zest","Peach","Mineral"}'::text[], 'Usually made to drink young.', null, null, null, 'published'),
  ('gr_0050', 'Muscat Blanc à Petits Grains', '{"Gelber Muskateller","Muskateller","Muscat Blanc"}'::text[], 'white',
   'A highly aromatic white grape of the Muscat family. In Austria it is called Gelber Muskateller or simply Muskateller.',
   '{}'::text[], null, null, null, null, 'published');

update public.grapes g set similar_grape_id = s.id, similar_note = 'One of its parents, known in Croatia as Tribidrag or Crljenak kaštelanski.' from public.grapes s where s.grape_code = 'gr_0028' and g.grape_code = 'gr_0037';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Blaufränkisch is one of its parents.' from public.grapes s where s.grape_code = 'gr_0014' and g.grape_code = 'gr_0040';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Often suggested as an alternative to it, for its fresh acidity and green notes.' from public.grapes s where s.grape_code = 'gr_0011' and g.grape_code = 'gr_0047';
update public.grapes set aliases = aliases || '{"Wyndruif"}'::text[] where grape_code = 'gr_0032';
update public.grapes set aliases = aliases || '{"Modra Frankinja"}'::text[] where grape_code = 'gr_0040';
update public.grapes set aliases = aliases || '{"Olaszrizling"}'::text[] where grape_code = 'gr_0039';

